window.SCHOOL_LISTENING={"../assets/media/0b5b23d090a98a5fd096b0b7f135dfd2319854e51346fe90046473a502b465f5.mp3":[{"id":"PPT_0b5b23d090a98a5f","audioId":"PPT_0b5b23d090a98a5f","title":"Book 3 · Unit 1 · RW · READING 1","subtitle":"READING 1 · source slide 37","duration":206.65,"cues":[{"start":0,"end":1.58,"text":"Endangered species.","coverage":1},{"start":2.78,"end":8.54,"text":"An endangered species is a group of animals or plants which could soon become extinct.","coverage":1},{"start":9.44,"end":14.86,"text":"Extinction happens when the last animal of the species has died out and there will be","coverage":1},{"start":14.86,"end":15.16,"text":"no","coverage":1},{"start":15.16,"end":15.6,"text":"more.","coverage":1},{"start":16.28,"end":24.16,"text":"Many species are nearly extinct and could disappear from the Earth very soon if we don't do anything to save them.","coverage":1},{"start":24.16,"end":28.4,"text":"There are many reasons why species become endangered,","coverage":1},{"start":29.02,"end":34.96,"text":"but most harm to species is due to human activities such as habitat destruction,","coverage":1},{"start":35.4,"end":37.16,"text":"hunting and overfishing.","coverage":1},{"start":38.58,"end":43.48,"text":"Habitat destruction is the main reason why animals become endangered.","coverage":1},{"start":44.26,"end":46.24,"text":"This happens in two ways.","coverage":1},{"start":46.24,"end":47.32,"text":"First,","coverage":1},{"start":47.82,"end":50.2,"text":"when humans move into a new area,","coverage":1},{"start":50.56,"end":53.88,"text":"they cut down trees to build houses and farms.","coverage":1},{"start":54.68,"end":57,"text":"This destroys the animal's habitat,","coverage":1},{"start":57.48,"end":61.66,"text":"the natural environment where plants or animals usually live,","coverage":1},{"start":62.26,"end":64.24,"text":"and leaves them without food.","coverage":1},{"start":65.18,"end":69.02,"text":"Animal habitats are also destroyed because of pollution.","coverage":1},{"start":69.02,"end":71.88,"text":"Dirty water from factories,","coverage":1},{"start":72.32,"end":73.72,"text":"which contains chemicals,","coverage":1},{"start":74.36,"end":75.32,"text":"ends up in rivers,","coverage":1},{"start":75.94,"end":82.42,"text":"and poisons used on farmland may even kill animals which live in the area.","coverage":1},{"start":83.92,"end":88.2,"text":"Endangered species are also the result of hunting and fishing.","coverage":1},{"start":89.2,"end":95.8,"text":"Animals such as the Arabian Oryx are nearly extinct because of the high price of their meat.","coverage":1},{"start":95.8,"end":99.96,"text":"Other animals are killed for their fur, bones,","coverage":1},{"start":100.32,"end":101.02,"text":"or skin,","coverage":1},{"start":101.5,"end":103.1,"text":"or just for sport.","coverage":1},{"start":104.08,"end":104.98,"text":"For example,","coverage":1},{"start":105.3,"end":112.46,"text":"some seal species are now almost extinct because they are killed for their fur to make coats.","coverage":1},{"start":113.36,"end":117.36,"text":"Tigers are shot to make medicine and tea from their bones,","coverage":1},{"start":118.12,"end":121.62,"text":"and crocodiles are caught to make bags and shoes.","coverage":1},{"start":121.62,"end":125.12,"text":"Large sea creatures like whales,","coverage":1},{"start":125.48,"end":125.72,"text":"tuna,","coverage":1},{"start":126.08,"end":131.3,"text":"and sharks have all become endangered species because of overfishing.","coverage":1},{"start":132.08,"end":136.54,"text":"Too many are caught to make special dishes that people like to eat,","coverage":1},{"start":137.06,"end":139.74,"text":"such as shark's fin soup or sushi.","coverage":1},{"start":141.28,"end":148.86,"text":"What steps can individuals and governments take to protect more animal and plant species from becoming endangered?","coverage":1},{"start":148.86,"end":153.16,"text":"We should try not to pollute natural areas,","coverage":1},{"start":154.02,"end":159.9,"text":"and farmers or companies who destroy animal habitats should face a financial penalty.","coverage":1},{"start":161.04,"end":165.94,"text":"The public can help out by refusing to buy products made from animals'","coverage":1},{"start":166.28,"end":167.08,"text":"body parts,","coverage":1},{"start":167.48,"end":170.84,"text":"such as seal fur coats or crocodile bags.","coverage":1},{"start":170.84,"end":172.94,"text":"Governments can help,","coverage":1},{"start":173.34,"end":173.36,"text":"too,","coverage":1},{"start":173.72,"end":176.3,"text":"by making it against the law to hunt,","coverage":1},{"start":176.68,"end":179.62,"text":"fish, or trade in endangered species.","coverage":1},{"start":180.46,"end":184.84,"text":"They can also provide funding for animal sanctuaries and zoos.","coverage":1},{"start":185.76,"end":190.84,"text":"These protect animals from extinction by breeding more endangered animals,","coverage":1},{"start":191.36,"end":193.98,"text":"which can later be released into the wild.","coverage":1},{"start":193.98,"end":197.98,"text":"If we all cooperate by taking these steps,","coverage":1},{"start":198.48,"end":204.82,"text":"we will protect our planet so that our children and their children can enjoy it, too.","coverage":1}],"file":"17e2bfde0cdaf9a1db5b.js","track":0,"media":"../assets/media/0b5b23d090a98a5fd096b0b7f135dfd2319854e51346fe90046473a502b465f5.mp3"}],"../assets/media/c7e6818264df7e3b267fd0544aca9b31457fc11439e74189978e23c9de2676d4.mp3":[{"id":"PPT_c7e6818264df7e3b","audioId":"PPT_c7e6818264df7e3b","title":"Book 3 · Unit 1 · RW · READING 2","subtitle":"READING 2 · source slide 91","duration":246.86,"cues":[{"start":0,"end":5.94,"text":"Invasive species are plants and animals which arrive in an area where they are not native,","coverage":1},{"start":6.36,"end":7.92,"text":"usually due to human activity.","coverage":1},{"start":8.56,"end":9.22,"text":"For example,","coverage":1},{"start":9.64,"end":17.94,"text":"a species of shellfish might attach itself to the outside of a ship traveling between countries and enter a new environment in this way.","coverage":1},{"start":18.96,"end":23.82,"text":"Invasive species are often able to grow quickly in their new homes because they have","coverage":1},{"start":23.82,"end":24.06,"text":"no","coverage":1},{"start":24.06,"end":25,"text":"natural enemies.","coverage":1},{"start":25.44,"end":26.32,"text":"As a result,","coverage":1},{"start":26.74,"end":31.54,"text":"they may replace or damage native plants and animals which live in the same environment.","coverage":1},{"start":32.44,"end":36.92,"text":"One example is the case of gray and red squirrels in the United Kingdom.","coverage":1},{"start":37.92,"end":42.44,"text":"Red squirrels used to be a common sight in British forests and countryside.","coverage":1},{"start":43.18,"end":53.74,"text":"Then, in the 1870s, the gray squirrel was introduced from North America because rich people thought the squirrels looked fashionable in the gardens of their large homes.","coverage":1},{"start":54.3,"end":54.98,"text":"Today,","coverage":1},{"start":55.62,"end":59.4,"text":"only about 140 ,000 red squirrels remain,","coverage":1},{"start":59.76,"end":60.96,"text":"mostly in Scotland.","coverage":1},{"start":61.68,"end":62.5,"text":"In contrast,","coverage":1},{"start":63.1,"end":70.62,"text":"gray squirrels are now extremely common and seen as major pests due to the damage they cause to plants and houses.","coverage":1},{"start":71.56,"end":73.2,"text":"While red squirrels are protected,","coverage":1},{"start":73.7,"end":76.42,"text":"gray squirrels can be legally trapped and destroyed.","coverage":1},{"start":77.46,"end":78.4,"text":"At first sight,","coverage":1},{"start":78.8,"end":80.9,"text":"the two species of squirrel are similar.","coverage":1},{"start":81.24,"end":86.3,"text":"They both have a long tail which helps them balance when jumping from tree to tree,","coverage":1},{"start":86.7,"end":88.42,"text":"and the same large eyes,","coverage":1},{"start":88.78,"end":89.54,"text":"small ears,","coverage":1},{"start":89.86,"end":91.46,"text":"and powerful back legs.","coverage":1},{"start":92.24,"end":93.08,"text":"In contrast,","coverage":1},{"start":93.44,"end":97.08,"text":"the two types of squirrel are different in body size and weight.","coverage":1},{"start":97.88,"end":107.88,"text":"The red squirrel has a typical head and body length of approximately 19 to 23 centimeters, a tail length of 15 to 20 centimeters,","coverage":1},{"start":108.48,"end":113.2,"text":"and a body weight of 250 to 340 grams.","coverage":1},{"start":114.12,"end":116.94,"text":"The gray squirrel is larger than the red squirrel.","coverage":1},{"start":117.66,"end":121.64,"text":"The head and body measure between 23 and 30 centimeters,","coverage":1},{"start":122.14,"end":126.18,"text":"and the tail is between 19 and 25 centimeters long.","coverage":1},{"start":127.18,"end":129.6,"text":"Adult gray squirrels are also heavier,","coverage":1},{"start":130.26,"end":133.34,"text":"weighing between 400 and 600 grams.","coverage":1},{"start":134.14,"end":139.44,"text":"This size allows them to store more fat and helps them to survive hard winters,","coverage":1},{"start":139.78,"end":142.38,"text":"which can be fatal to their smaller cousins.","coverage":1},{"start":144.02,"end":149.82,"text":"Three more differences explain why red squirrels have lost out in the competition with gray squirrels.","coverage":1},{"start":150.86,"end":151.28,"text":"First,","coverage":1},{"start":151.76,"end":154.08,"text":"red squirrels live high up in the trees,","coverage":1},{"start":154.62,"end":158.12,"text":"whereas gray squirrels spend most of their time on the ground.","coverage":1},{"start":159,"end":165.22,"text":"This means that any loss of forest habitat greatly affects the red squirrel population.","coverage":1},{"start":166.44,"end":173.9,"text":"Another reason is that gray squirrels are more intelligent and can adapt to new situations more easily than red squirrels.","coverage":1},{"start":174.72,"end":175.52,"text":"For example,","coverage":1},{"start":175.96,"end":182.1,"text":"they can survive in an urban environment because of their ability to use food provided by humans.","coverage":1},{"start":183.26,"end":186.18,"text":"A third problem for the red squirrel is disease.","coverage":1},{"start":186.98,"end":189.64,"text":"Both squirrels carry Parapox virus.","coverage":1},{"start":190.38,"end":195.3,"text":"The virus does not seem to affect gray squirrels, but it is fatal to reds.","coverage":1},{"start":196.84,"end":197.74,"text":"In conclusion,","coverage":1},{"start":198.06,"end":203.42,"text":"there does not seem to be much that scientists can do to help red squirrels survive in Britain.","coverage":1},{"start":204.4,"end":211.64,"text":"Some politicians support destroying populations of gray squirrels, but many British people would contend that this is cruel.","coverage":1},{"start":212.44,"end":216.5,"text":"Red squirrels have been successfully reintroduced from other countries,","coverage":1},{"start":216.98,"end":219.26,"text":"and they could be protected in places where there are","coverage":1},{"start":219.26,"end":219.46,"text":"no","coverage":1},{"start":219.46,"end":222.22,"text":"gray squirrels, such as the Isle of Wight.","coverage":1},{"start":223.1,"end":223.46,"text":"However,","coverage":1},{"start":224.08,"end":227.82,"text":"some people question whether Britain should protect red squirrels at all.","coverage":1},{"start":228.68,"end":229.36,"text":"Worldwide,","coverage":1},{"start":229.7,"end":231.66,"text":"they are not an endangered species.","coverage":1},{"start":232.46,"end":233.64,"text":"Considering the evidence,","coverage":1},{"start":234.06,"end":238.38,"text":"saving the red squirrel may be a waste of British government money.","coverage":1},{"start":238.38,"end":244.9,"text":"Government conservation funding should instead be spent on other endangered animals.","coverage":1}],"file":"a9ecbde90b9c985b8090.js","track":0,"media":"../assets/media/c7e6818264df7e3b267fd0544aca9b31457fc11439e74189978e23c9de2676d4.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 What do you know about dolphins? Where do they live and what do they eat?Possible answer: Dolphins are intelligent animals. They live in water and many eat fish.","slide":4,"shape":"15","bookPage":"16"},{"text":"2 What do birds eat? How do they get their food?Possible answer: Some birds eat insects and others eat fish. They may hunt, dig or catch food in the water.","slide":4,"shape":"16","bookPage":"16"},{"text":"1 Why and when might dolphins come onto land?Possible answer: They might come onto land briefly to catch food.","slide":6,"shape":"29","bookPage":"16"},{"text":"2 Why do you think dolphins live in groups, rather than alone?Possible answer: They may help and protect each other.","slide":6,"shape":"30","bookPage":"16"},{"text":"3 What do the dolphins and the birds have in common?Possible answer: Both animals eat fish and spend time near the water.","slide":6,"shape":"31","bookPage":"16"},{"text":"1  An egret is a white bird with long legs.","slide":14,"shape":"7","bookPage":"16"},{"text":"2  A marsh is an area of soft, wet land.","slide":14,"shape":"8","bookPage":"16"},{"text":"3  The dolphin rises to the surface of the water.","slide":14,"shape":"9","bookPage":"16"},{"text":"4  The bird stands on a mud bank beside the river.","slide":14,"shape":"10","bookPage":"16"},{"text":"5  The fish are pushed onto the shore.","slide":14,"shape":"11","bookPage":"16"},{"text":"6  Some birds depend on dolphins for food.","slide":14,"shape":"12","bookPage":"16"},{"text":"a  Young dolphins and egrets learn how to fish from their parents.  4","slide":17,"shape":"6","bookPage":"17"},{"text":"b  Dolphins and egrets live together in the marshes of South Carolina.  1","slide":17,"shape":"7","bookPage":"17"},{"text":"c  The dolphins’ fishing is the only way some egrets get food.  5","slide":17,"shape":"8","bookPage":"17"},{"text":"d  The egrets watch the dolphins in the water carefully.  2","slide":17,"shape":"9","bookPage":"17"},{"text":"e  The dolphins push the fish onto land.  3","slide":17,"shape":"10","bookPage":"17"},{"text":"1  The egrets are experts on the dolphins’ behaviour.  T","slide":20,"shape":"6","bookPage":"17"},{"text":"2  The dolphins push the egrets onto the shore.  The dolphins push the fish onto the shore.","slide":20,"shape":"7","bookPage":"17"},{"text":"3  When the fish are in the water, the dolphins start eating.  The dolphins start eating when the fish are out of the water.","slide":20,"shape":"8","bookPage":"17"},{"text":"4  The dolphins always use their left sides to push the fish.  They always use their right sides.","slide":20,"shape":"9","bookPage":"17"},{"text":"5  Some of the birds do not eat fish.  DNS","slide":20,"shape":"10","bookPage":"17"},{"text":"1 What other animals work together and help each other?Possible answer: Some birds eat harmful insects from the bodies of large mammals.","slide":22,"shape":"7","bookPage":"17"},{"text":"2 Why would two different animals work together?Possible answer: Animals may work together to find food, stay safe or survive.","slide":22,"shape":"19","bookPage":"17"},{"text":"3 What animals do humans work with? Why?Possible answer: People work with farm animals, and some dogs help people with disabilities.","slide":22,"shape":"21","bookPage":"17"},{"text":"The black rhino is one of the most endangered animals in the world. There are onlyabout 5,000 left today.","slide":33,"shape":"5","bookPage":"18"},{"text":"There are three species of bears in North America. They are the American blackbear, the grizzly bear and the polar bear.","slide":33,"shape":"15","bookPage":"18"},{"text":"Dangerous chemicals from factories can kill fish and other animals when theyenter lakes and rivers.","slide":34,"shape":"5","bookPage":"18"},{"text":"Smoke from factories can pollute the air and hurt both humans and animals.","slide":34,"shape":"18","bookPage":"18"},{"text":"When new homes are built, it often destroys the areas where animals live.","slide":35,"shape":"9","bookPage":"18"},{"text":"Few people visited the zoo last week due to the cold weather.","slide":35,"shape":"18","bookPage":"18"},{"text":"I don’t like zoos. I prefer to see animals in their natural environments.","slide":35,"shape":"5","bookPage":"18"},{"text":"Many organizations are working to protect endangered animals by creating safeplaces for them to live.","slide":35,"shape":"7","bookPage":"18"},{"text":"2 Look at the title and the first paragraph of the essay and answer the question.What is the difference between an endangered and an extinct species?Then complete the table with the names of any endangered and extinct species youknow.Answer: An endangered species may soon become extinct.An extinct species no longer exists: its last animal has died.The essay mentions tigers as endangered. Dodos and woolly mammoths areexamples of extinct animals.","slide":46,"shape":"19","bookPage":"18"},{"text":"endangered species\nextinct species\nTigers\nDodo; woolly mammoth","slide":47,"shape":"12","bookPage":"19"},{"text":"endangered species in the essay\nextinct species: examples\nArabian oryx; some seal species; tigers; crocodiles; whales; tuna; sharks\nDodo; woolly mammoth","slide":59,"shape":"14","bookPage":"19"},{"text":"a  How hunting and overfishing endanger animals  Paragraph 3","slide":69,"shape":"6","bookPage":"20"},{"text":"b  The definition of endangered and extinct species  Paragraph 1","slide":69,"shape":"7","bookPage":"20"},{"text":"c  How governments and citizens can protect animals  Paragraph 4","slide":69,"shape":"8","bookPage":"20"},{"text":"d  How humans destroy and pollute animal habitats  Paragraph 2","slide":69,"shape":"9","bookPage":"20"},{"text":"1 According to the essay, what is the main cause of animal extinction and endangeredspecies?Possible answer: Human activities are the main cause.","slide":71,"shape":"5","bookPage":"20"},{"text":"2 How does pollution and cutting down trees cause problems for animals?Possible answer: They destroy animal habitats and can leave animals without food or poison them.","slide":71,"shape":"19","bookPage":"20"},{"text":"3 What do people hunt animals for?Possible answer: People hunt animals for food, fur, skin, sport and products made from bones, suchas medicines and tea.","slide":72,"shape":"5","bookPage":"20"},{"text":"4 Which large sea creatures are endangered because of overfishing?Possible answer: Whales, tuna and sharks.","slide":72,"shape":"19","bookPage":"20"},{"text":"5 What can individuals do to protect animals from becoming endangered?Possible answer: Individuals can avoid polluting natural areas and refuse to buy products madefrom animals’ body parts.","slide":73,"shape":"5","bookPage":"20"},{"text":"6 What should governments invest in to get more animals back into the wild?Possible answer: Animal sanctuaries and zoos.","slide":73,"shape":"19","bookPage":"20"},{"text":"1 Companies who destroy animal habitats should pay a fine.Answer: Companies who destroy animal habitats should face a financial penalty.","slide":77,"shape":"7","bookPage":"20"},{"text":"2 You should help to protect animals by choosing not to buy fur.Answer: You should help to protect animals by refusing to buy fur.","slide":77,"shape":"16","bookPage":"20"},{"text":"3 We can make it illegal to hunt, fish or trade in endangered species.Answer: We can make it against the law to hunt, fish or trade in endangered species.","slide":77,"shape":"5","bookPage":"20"},{"text":"4 Governments can pay for animal sanctuaries and zoos.Answer: Governments can provide funding for animal sanctuaries and zoos.","slide":78,"shape":"5","bookPage":"20"},{"text":"5 If we work together by taking these actions, we can protect our planet.Answer: If we cooperate by taking these steps, we can protect our planet.","slide":78,"shape":"19","bookPage":"20"},{"text":"16. What was recorded before the beavers arrived?\nA. Plants and birds at fixed points\nB. The price of farmland\nC. Only visitors' opinions","slide":81,"shape":"5","bookPage":null},{"text":"17. Why was the pond edge mapped twice?\nA. To compare wet and dry conditions\nB. To count visitors\nC. To choose a new path","slide":82,"shape":"5","bookPage":null},{"text":"1 Are these animals common in your country?Possible answer: I have seen squirrels in parks, but I am not sure which species they were.","slide":97,"shape":"19","bookPage":"21"},{"text":"2 Which squirrel do you think is seen as a major pest? Why?Possible answer: Grey squirrels may be seen as pests because they can cause damage.","slide":97,"shape":"20","bookPage":"21"},{"text":"3 Which squirrel do you think was introduced to the UK from North America and which one is native to the UK?Possible answer: The grey squirrel is from North America, and the red squirrel is native to the UK.","slide":97,"shape":"21","bookPage":"21"},{"text":"4 Which squirrel do you think can survive best in difficult conditions?Possible answer: Grey squirrels may survive difficult conditions better because they are larger.","slide":98,"shape":"19","bookPage":"21"},{"text":"5 Which squirrel do you think is more likely to survive a disease or a virus?Possible answer: Grey squirrels may survive a disease more easily.","slide":98,"shape":"20","bookPage":"21"},{"text":"6 Some people say that it’s cruel to destroy one species of animal to help the other survive. Why do you think that is?Possible answer: People may think every animal has a right to live and should not be killed to help another species.","slide":98,"shape":"21","bookPage":"21"},{"text":"The grey squirrel is larger than the red squirrel. The head and body measure between (7)\n23 and (8) 30 cm, and the tail is between (9) 19 and (10)\n25 cm long.","slide":105,"shape":"6","bookPage":"22"},{"text":"4 Work in groups of four students, A, B, C and D. Read the text according to yourletter.In your notebook, take notes about the main ideas and details in your text. Check themeaning of any words you don’t know.Answer: Invasive species can damage or replace native species.Grey squirrels introduced from North America have become common in Britain.Habitat, adaptability and disease help explain the grey squirrel’s success.The author questions whether Britain should spend money protecting redsquirrels.","slide":116,"shape":"17","bookPage":"23"},{"text":"5 Work in your group from Exercise 4. Use your notes to share the information fromyour text.Answer: Invasive species can damage or replace native species.Grey squirrels introduced from North America have become common in Britain.Habitat, adaptability and disease help explain the grey squirrel’s success.The author questions whether Britain should spend money protecting redsquirrels.","slide":117,"shape":"17","bookPage":"23"},{"text":"2 Which squirrel do you think is seen as a major pest? Why?Answer: Grey squirrels.","slide":125,"shape":"7","bookPage":"23"},{"text":"3 Which squirrel do you think was introduced to the UK from North America and which one is native to the UK?Answer: Grey squirrels were introduced from North America; red squirrels are native to the UK.","slide":125,"shape":"16","bookPage":"23"},{"text":"4 Which squirrel do you think can survive best in difficult conditions?Answer: Grey squirrels.","slide":125,"shape":"5","bookPage":"23"},{"text":"5 Which squirrel do you think is more likely to survive a disease or a virus?Answer: Grey squirrels.","slide":126,"shape":"15","bookPage":"23"},{"text":"The article uses the example of the red and grey squirrel to explain what can happen when an invasive species competes with a native one. The grey squirrel was introduced from North America in the 19th century and has become very successful since then.","slide":139,"shape":"6","bookPage":"23"},{"text":"Now there are fewer than 140,000 native red squirrels left in the wild. The main reason why the grey squirrel is more successful is that it is heavier, so it is less affected by cold weather. Another reason is that grey squirrels are able to live in cities.","slide":140,"shape":"6","bookPage":"23"},{"text":"A further reason may be parapoxvirus, which kills red squirrels. Even though many people regard the grey squirrel as a pest, few British people support destroying grey squirrels. Because red squirrels are not endangered worldwide, perhaps they could be reintroduced to Britain.","slide":141,"shape":"6","bookPage":"23"},{"text":"A recent fire damaged or destroyed many of the city’s buildings. Choose the definition.a made worse b decreasedCorrect answer: a made worse","slide":149,"shape":"5","bookPage":"24"},{"text":"Loss of forest habitat affects red squirrels much more than grey squirrels. Choose the definition.a stops; prevents b influences; causes a change inCorrect answer: b influences; causes a change in","slide":149,"shape":"18","bookPage":"24"},{"text":"When organizations cooperate, they can do more to help endangered animals. Choose the definition.a work together b succeedCorrect answer: a work together","slide":150,"shape":"17","bookPage":"24"},{"text":"If people continue to hunt tigers, it will be impossible for them to survive. Choose the definition.a continue to live b find foodCorrect answer: a continue to live","slide":150,"shape":"19","bookPage":"24"},{"text":"Some governments provide land where animals can live safely. Choose the definition.a change b giveCorrect answer: b give","slide":151,"shape":"17","bookPage":"24"},{"text":"In many countries, farms have replaced wild, natural spaces where animals once lived. Choose the definition.a left empty b taken the place ofCorrect answer: b taken the place of","slide":151,"shape":"18","bookPage":"24"},{"text":"2 Work with a partner or small group. Answer the question.Imagine you are alone in a forest. What is the most important thing that you need to helpyou survive? A knife? A blanket? Explain your answer.Possible answer: I would choose a blanket because I would need to keep warm.","slide":153,"shape":"12","bookPage":"24"},{"text":"Elephants are bigger than mice.","slide":160,"shape":"19","bookPage":"25"},{"text":"Elephants are heavier than mice.","slide":160,"shape":"20","bookPage":"25"},{"text":"Lions are more dangerous than mice.","slide":160,"shape":"21","bookPage":"25"},{"text":"Whale sharks are larger than tiger sharks. Both have fins and a large mouth. However, tiger sharks can be more dangerous to humans.","slide":164,"shape":"6","bookPage":null},{"text":"Red squirrels depend on forest habitat. When forests are damaged, they lose food and shelter. This affects the red squirrel population.","slide":165,"shape":"6","bookPage":null},{"text":"12. Wildlife counts are repeated at fixed points with records of the date and weather.\nAnswer: C","slide":171,"shape":"5","bookPage":null},{"text":"15. The extent of water is checked in contrasting weather.\nAnswer: B","slide":171,"shape":"8","bookPage":null},{"text":"11. Paragraph A\nAnswer: iv","slide":174,"shape":"5","bookPage":null},{"text":"12. Paragraph B\nAnswer: i","slide":174,"shape":"8","bookPage":null},{"text":"Whale sharks are heavier than tiger sharks. Whereas whale sharks eat small sea creatures, tiger sharks eat tuna and turtles. Tiger sharks are more dangerous to humans. Both animals have fins.","slide":180,"shape":"6","bookPage":null},{"text":"The whale shark has a wide head and a spotted back. Its body is adapted to moving through water. A squirrel has fur and a bushy tail. These visible features make the animals easy to distinguish.","slide":181,"shape":"6","bookPage":null},{"text":"head and body: 19–23 cm","slide":190,"shape":"10","bookPage":"26"},{"text":"tail: 15–20 cm","slide":190,"shape":"11","bookPage":"26"},{"text":"weight: 250–340 g","slide":190,"shape":"12","bookPage":"26"},{"text":"have a head,\nbody and tail","slide":190,"shape":"15","bookPage":"26"},{"text":"need food to\nsurvive","slide":190,"shape":"16","bookPage":"26"},{"text":"head and body: 23–30\ncm","slide":190,"shape":"19","bookPage":"26"},{"text":"tail: 19–25 cm","slide":190,"shape":"20","bookPage":"26"},{"text":"weight: 400–600 g","slide":190,"shape":"21","bookPage":"26"},{"text":"Compare the sharks’ size.Correct answer: The whale shark is larger and longer than the tiger shark.","slide":195,"shape":"16","bookPage":"27"},{"text":"Compare the sharks’ colour.Correct answer: Their backs and sides have different colours, but both sharks have white stomachs.","slide":195,"shape":"17","bookPage":"27"},{"text":"Compare the sharks’ skin pattern.Correct answer: The whale shark has white spots and stripes; the tiger shark has dark stripes.","slide":195,"shape":"18","bookPage":"27"},{"text":"Compare the sharks’ mouths.Correct answer: The whale shark has a much wider mouth than the tiger shark.","slide":195,"shape":"19","bookPage":"27"},{"text":"Compare the sharks’ fins and tail.Correct answer: Both sharks have fins and tails, but their body markings differ.","slide":196,"shape":"19","bookPage":"27"},{"text":"1  Which shark is smaller?  T. Tiger shark","slide":200,"shape":"6","bookPage":"27"},{"text":"2  Which shark is heavier?  W. Whale shark","slide":200,"shape":"7","bookPage":"27"},{"text":"3  Which shark eats large animals?  T. Tiger shark","slide":200,"shape":"8","bookPage":"27"},{"text":"4  Which shark eats tiny sea creatures?  W. Whale shark","slide":200,"shape":"9","bookPage":"27"},{"text":"5  Which shark is in greater danger of extinction?  W. Whale shark","slide":200,"shape":"10","bookPage":"27"},{"text":"6  Which shark is more dangerous to humans?  T. Tiger shark","slide":200,"shape":"11","bookPage":"27"},{"text":"length: 5.5–10 m","slide":205,"shape":"9","bookPage":"28"},{"text":"weight: 18 tonnes","slide":205,"shape":"10","bookPage":"28"},{"text":"grey-blue back","slide":205,"shape":"11","bookPage":"28"},{"text":"light spots","slide":205,"shape":"12","bookPage":"28"},{"text":"white stomachs","slide":205,"shape":"14","bookPage":"28"},{"text":"large mouths","slide":205,"shape":"15","bookPage":"28"},{"text":"divided tails","slide":205,"shape":"16","bookPage":"28"},{"text":"fins for\nswimming","slide":205,"shape":"17","bookPage":"28"},{"text":"length: 3.0–4.2 m","slide":205,"shape":"19","bookPage":"28"},{"text":"weight: 0.86 tonnes","slide":205,"shape":"20","bookPage":"28"},{"text":"grey-brown back","slide":205,"shape":"21","bookPage":"28"},{"text":"striped pattern","slide":205,"shape":"22","bookPage":"28"},{"text":"eats plankton, krill and\nother tiny animals","slide":206,"shape":"9","bookPage":"28"},{"text":"endangered","slide":206,"shape":"10","bookPage":"28"},{"text":"no recorded attacks on\nhumans","slide":206,"shape":"11","bookPage":"28"},{"text":"Chondrichthyes\n(fish)","slide":206,"shape":"13","bookPage":"28"},{"text":"live in oceans","slide":206,"shape":"14","bookPage":"28"},{"text":"eats tuna, dolphins and\nturtles","slide":206,"shape":"16","bookPage":"28"},{"text":"not currently at risk of\nextinction","slide":206,"shape":"17","bookPage":"28"},{"text":"many reports of attacks\non humans","slide":206,"shape":"18","bookPage":"28"},{"text":"1 lives / The tiger shark / in tropical oceans / .The tiger shark lives in tropical oceans.","slide":212,"shape":"14","bookPage":"29"},{"text":"2 isn’t / the whale shark / However, / dangerous / .However, the whale shark isn’t dangerous.","slide":212,"shape":"15","bookPage":"29"},{"text":"The fact file reports no whale shark attacks on humans.","slide":216,"shape":"16","bookPage":"29"},{"text":"Whale sharks have light spots on their sides.","slide":216,"shape":"17","bookPage":"29"},{"text":"Tiger sharks live in oceans.","slide":216,"shape":"18","bookPage":"29"},{"text":"Tiger sharks eat tuna.","slide":217,"shape":"19","bookPage":"29"},{"text":"Whale sharks have a much greater weight than tiger sharks.","slide":217,"shape":"20","bookPage":"29"},{"text":"1 The whale shark has a grey-blue back. The whale shark has a white stomach.The whale shark has a grey-blue back and a white stomach.","slide":223,"shape":"14","bookPage":"29"},{"text":"2 The tiger shark is grey-brown. The tiger shark has a striped pattern on its body.The tiger shark is grey-brown and has a striped pattern on its body.","slide":223,"shape":"15","bookPage":"29"},{"text":"3 The tiger shark eats large sea creatures. The tiger shark can be dangerous to humans.The tiger shark eats large sea creatures and can be dangerous to humans.","slide":224,"shape":"14","bookPage":"29"},{"text":"4 The whale shark is not aggressive. The whale shark is not dangerous to swim with.The whale shark is not aggressive or dangerous to swim with.","slide":224,"shape":"15","bookPage":"29"},{"text":"The tiger shark eats large sea creatures, whereas the whale shark eats tiny sea creatures.","slide":229,"shape":"17","bookPage":"30"},{"text":"The whale shark is very large, but the tiger shark is much smaller.","slide":229,"shape":"18","bookPage":"30"},{"text":"1 have long tails: red squirrels — yes; grey squirrels — yes.Both red squirrels and grey squirrels have long tails.","slide":233,"shape":"14","bookPage":"30"},{"text":"2 are an endangered species: red squirrels — no; grey squirrels — no.Neither red squirrels nor grey squirrels are an endangered species.","slide":233,"shape":"15","bookPage":"30"},{"text":"GRAMMAR FOR WRITING6 In pairs, make up two sentences about your classmates using both, neither andnor. One student starts the sentence and the other student finishes.Student 1 starts: Neither [classmate 1] nor [classmate 2] …Student 2 finishes: … is wearing a hat.Answer: Both Mohamed and Bilaal wear glasses.Neither Fatima nor Jane has long hair.","slide":235,"shape":"15","bookPage":"30"},{"text":"1 Which sentences introduce paragraphs about differences?b Three more differences explain why red squirrels have lost out in the competition with grey squirrels.c In contrast, the two types of squirrel are different in body size and weight.","slide":248,"shape":"18","bookPage":"31"},{"text":"2 Which sentence introduces a paragraph about similarities?a At first sight, the two species of squirrel are similar.","slide":248,"shape":"19","bookPage":"31"},{"text":"3 In Reading 2, how many supporting sentences does each paragraph have? Are all the paragraphs the same length? What does this tell you about the correct number of sentences in a paragraph?The paragraphs have between one and seven supporting sentences. Their lengths differ, so there is no single correct number.","slide":249,"shape":"18","bookPage":"31"},{"text":"Completed paragraph: The American black bear and the grizzly, or brown, bear are similar in many ways. Both bear species are native to North America and are common in both the United States and Canada. Neither the black bear nor the grizzly bear is an endangered species. Despite their names, the species are also similar in colour. ‘Black’ bears can be black, brown, red and even white. In the same way, grizzlies can range in colour from black to blonde. Finally, the two bear species are similar in behaviour.","slide":255,"shape":"14","bookPage":"32"},{"text":"2 In the two texts, the topic sentences are missing. Read each text and its threepossible topic sentences (a–c). Circle the letter of two possible topic sentences foreach text.a African and Asian elephants are different in appearance, but they are similar socially.b African and Asian elephants have both differences and similarities.c African and Asian elephants are very similar in appearance.Answer: a African and Asian elephants are different in appearance, but they are similar socially.b African and Asian elephants have both differences and similarities.","slide":260,"shape":"12","bookPage":"32"},{"text":"Completed paragraph: African and Asian elephants are different in appearance, but they are similar socially. African elephants are much larger than Asian elephants and have much larger ears to protect them from the hot African sun. African elephants also have more wrinkled skin than their Asian cousins. Although the two species have tusks – large, curved teeth – only male Asian elephants have them, whereas both male and female African elephants do. However, despite these differences, the African and Asian species are similar in several important ways.","slide":261,"shape":"12","bookPage":"32"},{"text":"Whale sharks and tiger sharks differ in important ways. The whale shark is heavier than the tiger shark. It eats small sea creatures. In contrast, the tiger shark eats much larger animals.","slide":266,"shape":"6","bookPage":null},{"text":"The two animal groups face different problems. Group A has enough food but few nesting sites. Group B has many nesting sites, whereas its food supply is limited. The reserve should improve nesting space for Group A and food access for Group B.","slide":267,"shape":"6","bookPage":null},{"text":"The reserve’s squirrel groups have both similarities and differences. Both need places to nest. The red squirrel group uses woodland food, whereas the grey squirrel group also finds food near buildings. This gives the grey group more possible feeding areas in the reserve.","slide":268,"shape":"6","bookPage":null}];
